What is printed when the following program is run?

```python
class Person:
    def __init__(self, name):
        self.name = name
    def role(self):
        return "person"
    def intro(self):
        return self.name + " is a " + self.role()

class Teacher(Person):
    def role(self):
        return "teacher"

class Student(Person):
    pass

people = [Person("Ako"), Teacher("Neba"), Student("Fon")]
print(" | ".join(p.intro() for p in people))
```

What is printed when the following program is run?

```python
class Item:
    count = 0
    def __init__(self, price):
        self._price = price
        Item.count += 1
    def total(self, qty):
        return self._price * qty

class Discounted(Item):
    def __init__(self, price, rate):
        super().__init__(price)
        self.rate = rate
    def total(self, qty):
        return super().total(qty) * (1 - self.rate)

a = Item(1000)
b = Discounted(2000, 0.25)
c = Discounted(500, 0.5)
print(Item.count, a.total(3), b.total(2), c.total(4))
```
